        "svg": "<circle cx=\"290\" cy=\"212\" r=\"24\" fill=\"none\" stroke=\"#0f172a\" stroke-width=\"4.5\"/><circle cx=\"385\" cy=\"245\" r=\"26\" fill=\"none\" stroke=\"#0f172a\" stroke-width=\"4.5\"/>",
